  "Tell us where to send it. We’ll email the full guide right away, and you can start reading here.": "Díganos a dónde enviarla. Le enviaremos la guía completa por correo electrónico de inmediato, y puede empezar a leerla aquí.",
  "Also send me occasional news and event invitations from Alder Bend. Unsubscribe any time.": "Envíenme también noticias e invitaciones ocasionales a eventos de Alder Bend. Puedo cancelar la suscripción cuando quiera.",
