  "funding care, senior living 101 and the family decision toolkit. Download any of them, free.": "cómo pagar el cuidado, Senior Living 101 y el kit de decisiones para familias. Descargue cualquiera de ellas, gratis.",
  "Compare what staying at home really costs each month with life at Kestrel Point, from $5,100 a month with no second-person fee.": "Compare lo que realmente cuesta cada mes quedarse en casa con la vida en Kestrel Point, desde $5,100 al mes y sin cargo por segunda persona.",
  "A house has a lot of bills hiding in it. Add yours up, line by line, and see how they compare with one monthly rent at Kestrel Point.": "Una casa esconde muchas cuentas. Sume las suyas, renglón por renglón, y vea cómo se comparan con una sola renta mensual en Kestrel Point.",
  "Monthly figures. We’ve filled in typical Rivermead-area amounts; change any of them to match yours.": "Cifras mensuales. Hemos anotado montos típicos de la zona de Rivermead; cambie cualquiera para que coincida con los suyos.",
  "At Kestrel Point": "En Kestrel Point",
  "· about $10,000 a year saved": "· un ahorro de unos $10,000 al año",
  "Three restaurants on site": "Tres restaurantes en la comunidad",
  "Outings with our drivers, departing from the Lobby": "Salidas con nuestros choferes, desde el Vestíbulo",
  "25+ fitness classes a week on site": "Más de 25 clases de ejercicio por semana en la comunidad",
  "Events & Adventures on the calendar": "Eventos y Aventuras en el calendario",
  "Total at Kestrel Point": "Total en Kestrel Point",
