  "Your costs at home: $6,040 a month. At Kestrel Point: $5,550 a month.": "Sus costos en casa: $6,040 al mes. En Kestrel Point: $5,550 al mes.",
  "less at Kestrel Point": "menos en Kestrel Point",
  "Figures are estimates for planning. Rents shown are starting prices; Mateo Ruiz can give you exact pricing for the apartments open now at": "Las cifras son estimaciones para planificar. Las rentas que se muestran son precios iniciales; Mateo Ruiz puede darle los precios exactos de los departamentos disponibles ahora al",
  "Today’s classes, clubs, bus trips and happy hours at Kestrel Point in Rivermead, CA. Browse by day, week or month, filter by interest, sign up for trips online and print a large-print calendar.": "Las clases, clubes, paseos en autobús y happy hours de hoy en Kestrel Point, en Rivermead, CA. Consulte por día, semana o mes, filtre por interés, inscríbase en paseos en línea e imprima un calendario en letra grande.",
  "Gym": "Gimnasio",
  "Grant Ellison’s Activity Meeting is every Friday at 2:45 pm in The Bistro: next week’s events and changes, then drinks and appetizers before happy hour.": "La Reunión de Actividades de Grant Ellison es cada viernes a las 2:45 pm en The Bistro: los eventos y cambios de la próxima semana, y luego bebidas y botanas antes del happy hour.",
