  "Kestrel Point is owned, designed, built and run by Wrenhaven Senior Living. Our purpose, our six values and where our name comes from.": "Kestrel Point es propiedad de Wrenhaven Senior Living, que también la diseñó, la construyó y la administra. Nuestro propósito, nuestros seis valores y el origen de nuestro nombre.",
