  "Transportation": "Transporte",
  "Driver": "Conductor",
  "Apply for Driver": "Postularse para Conductor",
  "Maintenance": "Mantenimiento",
  "Maintenance Technician": "Técnico de Mantenimiento",
  "Apply for Maintenance Technician": "Postularse para Técnico de Mantenimiento",
  "Current openings, pay and applications are on our careers portal. A recruiter reviews every application.": "Las vacantes actuales, el salario y las solicitudes están en nuestro portal de empleo. Un reclutador revisa cada solicitud.",
  "Send a general application": "Enviar una solicitud general",
  "Map showing Kestrel Point at 4400 Kestrel Point Drive, Rivermead": "Mapa que muestra Kestrel Point en 4400 Kestrel Point Drive, Rivermead",
  "Just off Kestrel Road, a few blocks south of Rivermead Boulevard": "Junto a Kestrel Road, a pocas cuadras al sur de Rivermead Boulevard",
  "Minutes from Old Town Rivermead and Rivermead Regional Park": "A minutos de Old Town Rivermead y Rivermead Regional Park",
  "From Calder (I-5 South)": "Desde Calder (I-5 Sur)",
  "From Highway 99": "Desde la Highway 99",
  "About 25 to 30 minutes. Take I-5 South through Calder to the Rivermead Boulevard exit, and follow the directions above.": "De 25 a 30 minutos aproximadamente. Tome la I-5 Sur a través de Calder hasta la salida de Rivermead Boulevard y siga las indicaciones anteriores.",
  "Visitor parking is outside the main entrance. The community has secure gated access, so if the gate is closed, call the front desk on the main line.": "El estacionamiento para visitantes está afuera de la entrada principal. La comunidad tiene acceso seguro con portón; si el portón está cerrado, llame a la recepción a la línea principal.",
  "Front desk and Community Relations": "Recepción y Relaciones con la Comunidad",
  "Also listed": "También aparece",
