  "Address, directions, phone numbers, visiting information and who to ask for at Kestrel Point, 4400 Kestrel Point Drive, Rivermead, CA 95934.": "Dirección, indicaciones, números de teléfono, información para visitas y a quién preguntar en Kestrel Point, 4400 Kestrel Point Drive, Rivermead, CA 95934.",
  "The front entrance of the community": "La entrada principal de la comunidad",
  "By checking this box, I agree to receive recurring automated text messages from Kestrel Point at the mobile number provided, about": "Al marcar esta casilla, acepto recibir mensajes de texto automáticos y recurrentes de Kestrel Point en el número de celular proporcionado, sobre",
  "Book an in-person or video tour of Kestrel Point in Rivermead with Community Relations Director Mateo Ruiz.": "Reserve una visita en persona o por video a Kestrel Point en Rivermead con Mateo Ruiz, Director de Relaciones con la Comunidad.",
  "Tours by appointment": "Visitas con cita previa",
  "Stay for lunch": "Quédese a almorzar",
  "A live walk-through with Mateo from wherever you are.": "Un recorrido en vivo con Mateo desde donde usted esté.",
  "Stay for lunch.": "Quédese a almorzar.",
  "Join us in Meadowbrook Cafe or the Juniper Room after your tour.": "Acompáñenos en Meadowbrook Cafe o en The Juniper Room después de su visita.",
  "The daily specials from the Juniper Room and Meadowbrook Cafe.": "Las especialidades del día de The Juniper Room y Meadowbrook Cafe.",
  "— live or online — are arranged for residents and visitors who are deaf or hard of hearing, when appropriate. Let us know when you book.": "(en persona o en línea) se coordinan para residentes y visitantes sordos o con dificultades auditivas, cuando corresponda. Avísenos al reservar.",
  "Reasonable accommodations": "Adaptaciones razonables",
  "for people with disabilities, including hearing impairment. Just ask the front desk team.": "para personas con discapacidad, incluida la discapacidad auditiva. Solo pídalas al equipo de recepción.",
  "Kestrel Point is operated by": "Kestrel Point es operado por",
  "Kestrel Point’s accessibility statement: our WCAG 2.1 AA goal, text size, contrast and language tools, ASL interpreters and reasonable accommodations.": "Declaración de accesibilidad de Kestrel Point: nuestra meta WCAG 2.1 AA, herramientas de tamaño de texto, contraste e idioma, intérpretes de ASL y adaptaciones razonables.",
  "Kestrel Point is a home for everyone, and our website, printed materials and community spaces should be too.": "Kestrel Point es un hogar para todos, y nuestro sitio web, materiales impresos y espacios comunitarios también deben serlo.",
  "If you opt in to text messages, Kestrel Point will send you recurring automated texts about the topics you chose — such as your tour, the weekly activity calendar, daily menus, photos and news, Lantern updates or urgent notices.": "Si acepta recibir mensajes de texto, Kestrel Point le enviará mensajes automáticos y recurrentes sobre los temas que eligió, como su visita, el calendario semanal de actividades, los menús del día, fotos y noticias, novedades de Lantern o avisos urgentes.",
  "How Kestrel Point and Wrenhaven Senior Living collect, use and protect your information, our cookie policy and SMS terms.": "Cómo Kestrel Point y Wrenhaven Senior Living recopilan, usan y protegen su información, nuestra política de cookies y los términos de mensajes de texto.",
  "Kestrel Point is operated by Wrenhaven Senior Living. This policy explains what we collect when you use our website, how we use it and the choices you have.": "Kestrel Point es operado por Wrenhaven Senior Living. Esta política explica qué información recopilamos cuando usa nuestro sitio web, cómo la usamos y las opciones que usted tiene.",
  "Dimensions are approximate. Layouts vary slightly from apartment to apartment, so Mateo can show you the exact homes that are open.": "Las medidas son aproximadas. La distribución varía un poco de un departamento a otro, así que Mateo puede mostrarle exactamente los departamentos que están disponibles.",
  "Open now and ready to reserve. Join the alert list and we’ll tell you if another A1 opens up.": "Disponible ahora y listo para reservar. Únase a la lista de alertas y le avisaremos si se desocupa otro A1.",
