  "Assisted Living Services delivered in every apartment at Wrenhaven communities in Fairhollow and Rivermead, so residents can age in place.": "Servicios de Vida Asistida brindados en cada departamento de las comunidades Wrenhaven de Fairhollow y Rivermead, para que los residentes puedan envejecer en su hogar.",
  "Aging in place": "Envejecer en su hogar",
  "When your needs change, your address doesn’t. The resident services team tailors support to you, delivered privately in your own apartment, and adjusts it as you go.": "Cuando sus necesidades cambian, su dirección no cambia. El equipo de servicios para residentes adapta el apoyo a usted, se lo brinda en privado en su propio departamento y lo ajusta con el tiempo.",
