  "Ceramics, music, pet therapy, therapeutic storytelling and gardening": "Cerámica, música, terapia con mascotas, narración terapéutica y jardinería",
  "Outings to museums, golf and more, even stand-up paddling": "Salidas a museos, al golf y más, incluso paddle surf",
  "Fitness classes designed by the Fitness Director": "Clases de ejercicio diseñadas por el Director de Acondicionamiento Físico",
  "Lantern Memory Care at": "Lantern (cuidado de la memoria) en",
